import { expect, type Page } from "@playwright/test";

/** Shared steps for lesson e2e specs (generated by `npm run new-lesson`). */

/** A returning visitor with a route, so "/" shows the contents instead of the opening quiz. */
export async function seedRoute(page: Page, route = "newcomer") {
  await page.addInitScript((r) => {
    if (!localStorage.getItem("bon:v1")) {
      localStorage.setItem("bon:v1", JSON.stringify({ v: 1, route: r, completions: [], evidence: {} }));
    }
  }, route);
}

/** Presses Next in the stage bar. */
export async function nextStep(page: Page) {
  const next = page.getByRole("button", { name: "Next step" });
  await expect(next).toBeEnabled();
  await next.click();
}

/** Picks one answer per question (in order) in the lesson's Check, then checks them. */
export async function answerCheck(page: Page, answers: string[]) {
  const check = page.getByRole("region", { name: "Quick check" });
  const groups = check.getByRole("radiogroup");
  await expect(groups).toHaveCount(answers.length);
  for (const [i, a] of answers.entries()) {
    await groups.nth(i).getByRole("radio", { name: a, exact: true }).check();
  }
  await check.getByRole("button", { name: "Check answers" }).click();
  await expect(check.getByRole("status")).toHaveText(/All right/);
}

type Completion = { lessonId: string; stage: number; route: string; mode: string; evidence?: object };

/** The lesson's completion record, read through the app's test hook. */
export function completionOf(page: Page, lessonId: string) {
  return page.evaluate((id) => {
    const w = window as unknown as { __bookOfNear?: { progress?: { completions(): Completion[] } } };
    return w.__bookOfNear?.progress?.completions().find((c) => c.lessonId === id);
  }, lessonId);
}
